import { languageType } from "@/types/language";
import { Message } from "@arco-design/web-react";
import i18next from "i18next";
import _ from 'lodash';
import { action, observable, makeObservable, computed } from 'mobx';


i18next.init({
    returnNull: false,  // 设置为 true 时，未匹配到时返回 null
    returnEmptyString: false,  // 设置为 true 时，未匹配到时返回空字符串
});


/**
 * 全局页面数据
 */
class Language {

    options: Array<{ value: languageType, label: string }> = [
        {
          value: 'zh-CN',
          label: '中文'
        },
        {
          value: 'en-US',
          label: 'English'
        },
        {
          value: "zh-HK",
          label: "繁体"
        },
        {
          label: '德语',
          value: 'de-DE',
        },
        {
          label: '法语',
          value: 'fr-FR',
        },
        {
          label: "俄语",
          value: "ru-RU"
        },
        {
          label: '日语',
          value: 'ja-JP',
        }
    ]

    // 当前承租人
    lang: languageType = 'zh-CN';

    get langName(){
      return this.options.find((o) => o.value == this.lang)?.label || this.lang;
    }

    // 设置语言
    setLang = (key: languageType) => {
        this.lang = key;
    };

    constructor(){
        makeObservable(this, {
            lang: observable,
            setLang: action,
            langName: computed,
        });
    }

    init = () => {
      const storageLang = sessionStorage.getItem('storage-lang');
      if(storageLang && storageLang !== this.lang){
        this.changeLang(storageLang as any);
      }
    }

    // 切换多语言
    changeLang = async (lng: languageType) => {
        try {
            const mod = import.meta.glob('./lang/[a-z[]*.ts');
            const response = await mod[`./lang/${lng}.ts`]();
            const translations = await response.default;
            i18next.addResourceBundle(lng, 'translation', translations, true, true);
            i18next.changeLanguage(lng);
            this.setLang(lng);
        } catch (error) {
            Message.error(`${lng}语言切换失败`)
        }
    }
}

export default new Language();