import axios from "axios";
import config from 'mainConfig';

let ivKey: string = "d3VRYzJKUmFxem1S";
let publicKey: string;

// export const ajaxUrl = "/codes";
export const ajaxUrl = `${config.apiUrl}${import.meta.env.VITE_API_BASE_PATH}`;

console.log('config', config);

/**
 * @name 获取公钥
 */
const getPublicKey = async () => {
    const key = 'store-public-key';
    if(!publicKey){
        const localPublicKey = localStorage.getItem(key);
        if(localPublicKey){
            // 本地存在公钥，可以直接使用，异步请求公钥信息
            publicKey = localPublicKey;
            return publicKey;
        }
        await axios.get(ajaxUrl + '/publicKey', {}).then(({ data }: any) => {
            publicKey = data.data;
            localStorage.setItem(key, publicKey);
        })
    }
    return publicKey;
}


/**
 * @name RSA 加密
 */
export const getEncryptedKey = async function(pwd: string) {
    const forge = await import('node-forge');
    const publicKeyPem = await getPublicKey(); 
    const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);
    // 加密
    const encrypted = publicKey.encrypt(pwd, 'RSA-OAEP');
    return forge.util.encode64(encrypted);
}

// 生成指定长度的随机字符串
export async function generateRandomString(length = 16) {
    const forge = await import('node-forge');
    const bytes = forge.random.getBytesSync(length);
    const hexString = forge.util.bytesToHex(bytes);
    return hexString.slice(0,length);
}


const getAESKey = (key: string) => {
    return new Array(16).fill(key).join('').slice(0,16);
}

/**
 * @name AES 加密
 * @param crykey 密钥
 * @param data 要加密数据
 */
export const aseEncrypt = async (crykey: string, data: any) => {
    const forge = await import('node-forge');
    const iv = forge.util.createBuffer(ivKey).getBytes();
    const key = forge.util.createBuffer(crykey).getBytes();
    // 创建加密器
    const cipher = forge.cipher.createCipher('AES-CBC', key);
    cipher.start({ iv });

    // 加密数据
    cipher.update(forge.util.createBuffer(JSON.stringify({ data }) ));
    cipher.finish();

    // 获取加密后的数据和 IV（可选）
    const ciphertext = cipher.output.getBytes();
    const ciphertextStr = forge.util.bytesToHex(ciphertext);

    return ciphertextStr;
};

/**
 * @name AES 解密
 * @param crykey 密钥（和加密时一致）
 * @param data 要解密数据
 */
export const aseDecrypt = async (crykey: string, data: any, ivK: string = ivKey) => {
    const forge = await import('node-forge');
    const iv = forge.util.createBuffer(getAESKey(ivK)).getBytes();
    const ciphertextBytes = forge.util.hexToBytes(data);
    const key = forge.util.createBuffer(getAESKey(crykey)).getBytes();
    // 创建解密器
    const decipher = forge.cipher.createDecipher('AES-CBC', key);
    decipher.start({ iv });

    // 解密数据
    decipher.update(forge.util.createBuffer(ciphertextBytes));
    decipher.finish();

    // 获取解密后的数据
    const decrypted = JSON.parse(decipher.output.toString('utf8'));
    return decrypted.data;
};
