import { TreeSelect, TreeSelectProps } from "@arco-design/web-react";
import { useEffect, useMemo, useState } from "react";
import datas from './datas';
import { ParamsProps, TreeDatasProps } from "./interface";

/**
 * 返回层级选择数据（不支持分页加载）
 * 需要一次性加载所有选择数据
 */
export interface TreeSelectorProps extends TreeSelectProps {
    type?: string;
    // 会将参数作为数据源传给查询接口
    findParams?: Record<string, any>;
}

const TreeSelector = ({ type, findParams, ...props }: TreeSelectorProps) => {

    const { find, treeProps } = useMemo(() => {
        const item: TreeDatasProps = datas[type];
        if(!item) return {
            treeProps: {}
        };
        const { find, ...itemProps } = item;

        return {
            find,
            treeProps: itemProps,
        }
    },[type])

    const [treeData, setTreeData] = useState<any[]>([]);

    useEffect(() => {
        if(type){
            if(find){
                find({ params: findParams } as ParamsProps).then((list) => {
                    setTreeData(list);
                })
            }
        }
    },[type])


    return (
        <TreeSelect
            treeData={treeData}
            treeCheckStrictly={true}
            placeholder="请选择"
            allowClear
            fieldNames={{
                key: 'id',
                title: 'name',
            }}
            {...treeProps}
            {...props}
        />
    )
}


export default TreeSelector;