import { Message, Modal } from '@arco-design/web-react';
import { forwardRef, useMemo, useRef, useState } from 'react';
import Page, { SchemaPageProps } from '../Page';
import _ from 'lodash';
import Store from './store';
import { ApiJsonProps, JoinItem } from './interface';
import ajax from 'ajax';

export interface SechamApiJsonPageProps extends SchemaPageProps {
    apijson: ApiJsonProps;
    joins?: JoinItem[],
    // 不进行分页
    notPagination?: boolean;
}

function APiJsonPage({  apijson, joins, notPagination, ...props }: SechamApiJsonPageProps, ref){
    const {
        tableName,
        uniqueKey = 'id',
        findParams = {},
        postParams = {},
        processTableData,
        notEdit = false,
        notAdd = false,
        notDel = false,
        delConfirm,
        delMessage,
        getParams,
        showView = false,
        logging = false
    } = apijson;
    const { schemaTable, schema, treeBool, treeConfig } = props;

    const [store] = useState(() => new Store({ schema, joins, apijson }));


    const tableColumn = useMemo(() => {
        if(!schema) return [];
        const schemaKeys = Object.keys(schema.properties || {});
        let filterKeys = schemaTable?.filterKeys || props.tableFilterKeys || schemaKeys;
        if(treeBool){
            const { key = 'id', parentKey = 'parentId' } = treeConfig || {};
            filterKeys = Array.from(new Set([...filterKeys, key, parentKey]));
        }
        if(filterKeys){
            if(filterKeys.includes(uniqueKey)){
                return filterKeys;
            }
            return [uniqueKey, ...filterKeys]
        }
        return []
    },[])

    const api = useMemo(() => {
        return  {
            find: ({ pageSize, current, ...params}) => {
                const joinParams = store.getJoinsParams(params);
                const findColumns = tableColumn.filter((k) => !store.tables[k] && !store.fields[k]);
                return ajax.post('/apijson/gets', {
                    [`${tableName}[]`]: {
                        "query": 2,
                        page: current,
                        count: notPagination? 0 : pageSize,
                        [`${tableName}`]: {
                            ...store.queryParams(params),
                            // '@order': 'sort+',
                            "@column": findColumns.length? findColumns.join(',') : undefined,
                            ...findParams
                        },
                        ...joinParams,
                    },
                    "info@":`/${tableName}[]/info`
                }).then((res) => {
                    return {
                        list: processTableData? processTableData(res[tableName]) : res[tableName],
                        total: res.info.total
                    }
                })
            },
            get: (item) => {
                const joinParams = store.getJoinsParams({});
                return ajax.post('/apijson/gets', {
                    [`${tableName}[]`]: {
                        page: 1,
                        count: 0,
                        [`${tableName}`]: {
                            [uniqueKey]: item[uniqueKey]
                        },
                        ...joinParams,
                    },
                }).then((res) => {
                    
                    return store.getData(res[tableName][0]);
                })
            },
            post: (form) => {
                const { sparams, bus } = store.getJoinSave(form);
                const pParams = typeof postParams === "function"? postParams() : postParams;
                if(Object.keys(bus).length){
                    return ajax.post('/apijson/transaction', {
                        ...bus,
                        post: {
                            [`${tableName}`]: {
                                ...form,
                                ...pParams,
                            },
                            ...sparams,
                            ...bus.post,
                        },
                    }).then(() => {
                        Message.success({
                            content: '新增成功',
                        });
                    })
                }
                return ajax.post('/apijson/post', {
                    [`${tableName}`]: {
                        ...form,
                        ...pParams,
                    },
                    ...sparams,
                }).then(() => {
                    Message.success({
                        content: '新增成功',
                    });
                })
            },
            put: (form) => {
                const data = store.data;
                const tableParams = {
                    [`${uniqueKey}`]: data[uniqueKey],
                    ...form,
                }
                const { sparams, bus } = store.getJoinSave(tableParams, data);
                if(treeBool){
                    const { key = 'id', parentKey = 'parentId', errMsg } = treeConfig || {};
                    if(form[parentKey] == data[key]){
                        Message.error(errMsg || `不能选择自己作为上级`)
                        return Promise.reject();
                    }
                }
                if(Object.keys(bus).length){
                    if(!bus.put) bus.put = {};
                    _.assign(bus.put, {
                        [`${tableName}`]: tableParams,
                        ...sparams,
                    })
                    return ajax.post('/apijson/transaction', bus).then(() => {
                        Message.success({
                            content: '更新成功'
                        })
                    })
                }else {
                    return ajax.post('/apijson/put', {
                        [`${tableName}`]: tableParams,
                        ...sparams,
                    }).then(() => {
                        Message.success({
                            content: '更新成功'
                        })
                    })
                }
            },
            del: (item) => {
                return new Promise((resolve, reject) => {
                    const delOnOk = () => {
                        return ajax.post('/apijson/delete', {
                            [`${tableName}`]: {
                                [`${uniqueKey}`]: item[uniqueKey]
                            }
                        }).then((res) => {
                            Message.success({
                                content: '删除成功',
                            })
                            resolve(res)
                        }).catch(reject);
                    }
                    // 删除提示
                    if(treeBool && item.children.length){
                        return Message.warning("请删除当前子级数据后，在进行当前数据删除")
                    }else if(delConfirm !== false){
                        const keys = schemaTable?.filterKeys || props.tableFilterKeys || Object.keys(props.schema?.properties);
                        let title: string = `请确认是否要删除"${item.name || item[keys[0]]}"?`;
                        if(delMessage){
                            title = delMessage(item);
                        }
                        Modal.confirm({
                            title: title,
                            onOk: delOnOk,
                            onCancel: reject,
                        })
                    }else {
                        delOnOk();
                    }
                })
            },
            log: (item, { current, pageSize }) => {
                console.log('pageRef', pageRef)
                return ajax.get('/log/tableLog', {
                    tablename: tableName,
                    key: item[uniqueKey],
                    page: current,
                    size: pageSize,
                }).then((res) => {
                    return {
                        list: res.list,
                        total: res.total
                    }
                })
            },
        }
    }, [])

    const pageRef = ref || useRef<any>()

    const schemaTableProps = useMemo(() => {
        if(notPagination){
            return {
                pagination: false,
                ...schemaTable,
            }
        }
        return schemaTable;
    },[])
    
    if(!tableName || !schema){
        return null;
    }
    return (
        <Page
            {...props}
            ref={pageRef}
            schemaTable={schemaTableProps}
            api={{
                find: api.find,
                get: api.get,
                getDetail: showView? api.get : undefined,
                post: notAdd? undefined : api.post,
                put: notEdit? undefined : api.put,
                del: notDel? undefined : api.del,
                getParams: getParams,
                log: logging? api.log: undefined,
                ...props.api
            }}
        />
    )
}

export default forwardRef(APiJsonPage);