import { Button, Form, FormProps, Grid, Space } from "@arco-design/web-react"
import { memo, useMemo, useState } from "react";
import AsyncButton from "@system/AsyncButton";
import { IconDown, IconUp } from "@arco-design/web-react/icon";
import './index.less';
import Store from './store';
import { useObserver } from "mobx-react-lite";
import _ from "lodash";
import { schemaToFormItem, tableSchemaToSearchSchema } from "../utils";
import i18next from "i18next";
import FormGenerate from "../FormGenerate";


export interface SchemaQueryFormProps extends FormProps {
    schema?: JSONSchema | JSONSchema[];
    tableSchema?: JSONSchema;
    // 标签宽度
    labelWidth?: string | number;
    /**
     * 需要过滤展示的schema 数据
     */
    filterKeys?: string[];
    onSubmit?: (params: any) => any;
}

interface QueryButtonProps {
    store: Store
}

function QueryForm ({
    form: parentForm,
    schema: searchSchema,
    tableSchema,
    filterKeys,
    onSubmit,
    labelWidth = `130px`,
    ...props
}: SchemaQueryFormProps){
    
    const [form] = parentForm? [parentForm] : Form.useForm();
    const [store] = useState(() => new Store());

    return useObserver(() => {

        const schema = useMemo(() => {
            return searchSchema || tableSchemaToSearchSchema(tableSchema)
        },[searchSchema, tableSchema])

        

        /**
         * 表单搜索
         */
        const onSearch = () => {
            const params = form.getFieldsValue();
            if(onSubmit){
                return onSubmit(params);
            }
        }

        const formList = useMemo(() => {
            let list:any[] = [];
            if(schema && !Array.isArray(schema)){
                list = schemaToFormItem(schema)
                if(filterKeys){
                    const map =  new Map(list.map((o) => [o.field, o]));
                    list = filterKeys.map((k) => map.get(k)).filter((o) => Boolean(o));
                }
            }
            return list.map((o) => {
                // 查询表单所有项设置为非必填
                if(o.valueType === "input"){
                    o.fieldProps = _.assign({
                        onPressEnter: onSearch
                    }, o.fieldProps || {})
                }
                if(o.fieldProps){
                    // 查询模式下，只读和禁用没有意义
                    delete o.fieldProps.disabled;
                    delete o.fieldProps.readOnly;
                }
                return _.omit(o, 'rules', 'show', 'colProps') as any;
            });
        },[schema, filterKeys])

    
        const QueryButton = useMemo(() => {

            return  ({ store }) => {

                return useObserver(() => {



                    // 是否需要展开和收起按钮
                    const isAllVisible = formList.length >= store.columnSpan;
            
                    return (
                        <Space style={{ width: '100%' }} className="justify-end">
                            <Button
                                onClick={() => {
                                    form.clearFields();
                                }}
                            >{i18next.t('sys.reset')}</Button>
                            <AsyncButton
                                key="id"
                                type="primary"
                                onClick={onSearch}
                            >{i18next.t('sys.query')}</AsyncButton>
                            {isAllVisible && (store.isAll? (
                                <Button type="text" onClick={() => store.setIsAll(false)}>
                                    {i18next.t('sys.collapse')}<IconUp />
                                </Button>
                            ):(
                                <Button type="text" onClick={() => store.setIsAll(true)}>
                                    {i18next.t('sys.expand')}<IconDown />
                                </Button> 
                            ))}
                        </Space>
                    )
                })
            }

        },[formList])
    
        const generagte = useMemo(() => {

            const list = store.isAll? formList : formList.slice(0, store.columnSpan - 1);
            
            
            const getOffset = () => {
                if(store.isAll){
                    return ((store.columnSpan - list.length%store.columnSpan) - 1) * store.colSpan;
                }else {
                    return ((store.columnSpan - list.length) -1) * store.colSpan;
                }
            }
            return (
                <FormGenerate
                    colSpan={store.colSpan}
                    formList={[
                        ...list,
                        {
                            field: 'id',
                            colProps: {
                                span: store.colSpan,
                                offset: getOffset(),
                            },
                            formItemProps: {
                                label: '',
                            },
                            valueType: "input",
                            fieldProps: {
                                store,
                            } as any,
                            render: () => {
                                return <QueryButton store={store} />
                            }
                        }
                    ]}
                />
            )
        },[formList, filterKeys, store.isAll])


        if(formList.length === 0) return null;
    
        return (
            <Form
                className="schema-query-form"
                style={{ marginBottom: 20 }}
                form={form}
                labelCol={{
                    style: { maxWidth: labelWidth }
                }}
                wrapperCol={{
                    style: { flex: '1 0 100px' }
                }}
                {...props}
            >
                <Grid.Row>
                    {generagte}
                </Grid.Row>
            </Form>
        )
    })
}

export default memo(QueryForm);